from entities import User,  Container, ContainerTypefrom helpers.search import Paginationfrom schemas.topic import CreateTopicfrom services.container import ContainerServicefrom sqlalchemy.ext.asyncio import AsyncSessionfrom utils.container import ContainerSearchParamsfrom utils.post import generate_slugclass TopicService(ContainerService):    def __init__(self, session: AsyncSession):        super().__init__(session)    async def get_topics(self, pagination: Pagination) -> list[tuple[Container, User]]:        return await self.repository.get_metrics_containers(ContainerType.TOPIC, **pagination.dict())    async def get_full_topic(self, topic_id: int) -> tuple[Container, User]:        return self.ensure_one_return(            await self.repository.get_metrics_container(ContainerType.TOPIC, topic_id)        )    async def get_topic(self, topic_id) -> Container:        return await self.get_by_or_raise(id=topic_id, type=ContainerType.TOPIC)    async def create_topic(        self,        topic: CreateTopic,        author_id: int,    ) -> Container:        topic.slug = generate_slug(topic.slug)        await self.check_already_exists(slug=topic.slug, type=ContainerType.TOPIC)        topic = await self.create_item(            **topic.dict(),            type=ContainerType.TOPIC,            author_id=author_id        )        return topic    async def search_topic(            self, pagination: Pagination,            search: ContainerSearchParams    ) -> list[Container]:        return await self.search_container(            type_=ContainerType.TOPIC, search=search, pagination=pagination        )